import sys

MOD = 998244353
V = 100000

def main():
    z = list(map(int, sys.stdin.buffer.read().split()))
    n = z[0]
    a = z[1:]

    phi = list(range(V + 1))
    for p in range(2, V + 1):
        if phi[p] == p:
            for j in range(p, V + 1, p):
                phi[j] -= phi[j] // p

    divisors = [[] for _ in range(V + 1)]
    for d in range(1, V + 1):
        for j in range(d, V + 1, d):
            divisors[j].append(d)

    sums = [0] * (V + 1)
    out = []
    answer = 0
    weight = 1
    last = 0
    last_query = 0
    for x in a:
        if x == last:
            query = (last_query + weight * x) % MOD
        else:
            query = 0
            for d in divisors[x]:
                query += phi[d] * sums[d]
            query %= MOD
        answer = (2 * answer + query) % MOD
        out.append(str(answer))
        for d in divisors[x]:
            sums[d] += weight
            if sums[d] >= MOD:
                sums[d] -= MOD
        last = x
        last_query = query
        weight = (weight << 1) % MOD
    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    main()

