import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    a = data[1:]
    m = max(a)

    # Smallest prime factor for every number up to the maximum input.
    spf = [0] * (m + 1)
    for i in range(2, m + 1):
        if spf[i] == 0:
            spf[i] = i
            if i * i <= m:
                for j in range(i * i, m + 1, i):
                    if spf[j] == 0:
                        spf[j] = i

    # omega[x] is the number of prime factors of x, with multiplicity.
    omega = [0] * (m + 1)
    for x in range(2, m + 1):
        omega[x] = omega[x // spf[x]] + 1

    nim_sum = 0
    for x in a:
        nim_sum ^= omega[x]
    print("Anna" if nim_sum else "Bruno")

if __name__ == "__main__":
    main()

