import sys

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data:return
    n,q=data[:2]; p=list(range(n+1)); sz=[1]*(n+1); l=list(range(n+1)); r=list(range(n+1)); col=list(range(n+1)); cnt=[0]*(n+1)
    for i in range(1,n+1):cnt[i]=1
    def find(x):
        while p[x]!=x:
            p[x]=p[p[x]]; x=p[x]
        return x
    def union(a,b):
        a=find(a); b=find(b)
        if a==b:return a
        if sz[a]<sz[b]:a,b=b,a
        p[b]=a; sz[a]+=sz[b]; l[a]=min(l[a],l[b]); r[a]=max(r[a],r[b])
        return a
    out=[]; k=2
    for _ in range(q):
        t=data[k];k+=1
        if t==1:
            x=data[k]; c=data[k+1];k+=2
            root=find(x); old=col[root]
            if old!=c:
                cnt[old]-=sz[root];cnt[c]+=sz[root];col[root]=c
            L=l[root];R=r[root]
            if L>1:
                a=find(L-1)
                if col[a]==c: root=union(root,a)
            if R<n:
                a=find(R+1)
                if col[a]==c: root=union(root,a)
        else:
            c=data[k];k+=1;out.append(str(cnt[c]))
    print('\n'.join(out))
main()

