class Solution:
    def maxSubarrays(self, n: int, conflictingPairs) -> int:
        buckets = [[] for _ in range(n + 1)]
        m = len(conflictingPairs)
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            buckets[b].append((a, i))

        gain = [0] * m
        top1_a, top1_id = 0, -1
        top2_a, top2_id = 0, -1
        baseline = 0

        for right in range(1, n + 1):
            for a, idx in buckets[right]:
                if a > top1_a:
                    top2_a, top2_id = top1_a, top1_id
                    top1_a, top1_id = a, idx
                elif a > top2_a:
                    top2_a, top2_id = a, idx

            baseline += right - top1_a
            if top1_id != -1:
                gain[top1_id] += top1_a - top2_a

        return baseline + max(gain)

