import sys

def main():
    rd = sys.stdin.buffer.readline
    N, M, Q = map(int, rd().split())
    edges = []
    for _ in range(M):
        a, b, c = map(int, rd().split())
        edges.append((a - 1, b - 1, c))

    queries = []
    closed = set()
    for _ in range(Q):
        t, *v = map(int, rd().split())
        if t == 1:
            e = v[0] - 1
            queries.append((1, e))
            closed.add(e)
        else:
            queries.append((2, v[0] - 1, v[1] - 1))

    INF = 10**30
    dist = [[INF] * N for _ in range(N)]
    for i in range(N):
        dist[i][i] = 0
    for e, (a, b, w) in enumerate(edges):
        if e not in closed:
            dist[a][b] = dist[b][a] = w

    # Initial roads are fixed; compute all-pairs shortest paths.
    for k in range(N):
        dk = dist[k]
        for i in range(N):
            di = dist[i]
