import sys


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, budget = data[0], data[1]
    machines = []
    pos = 2
    for _ in range(n):
        a, p, b, q = data[pos:pos + 4]
        pos += 4
        machines.append((a, p, b, q))

    def minimum_cost(w, a, p, b, q):
        best = 10**30
        # An optimum exists with fewer than b S-machines, or fewer than
        # a T-machines; enumerate both possibilities.
        for s in range(b):
            remaining = w - a * s
            t = 0 if remaining <= 0 else (remaining + b - 1) // b
            best = min(best, s * p + t * q)
        for t in range(a):
            remaining = w - b * t
            s = 0 if remaining <= 0 else (remaining + a - 1) // a
            best = min(best, t * q + s * p)
        return best

    def feasible(w):
        total = 0
        for a, p, b, q in machines:
            total += minimum_cost(w, a, p, b, q)
            if total > budget:
                return False
        return True

    # Capacity cannot exceed 100 products per yen times the budget.
    low, high = 0, 100 * budget + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid
    print(low)


if __name__ == '__main__':
    solve()

