class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        length = len(s)

        # Binomial coefficients for the number of completions of a prefix.
        comb = [[0] * (length + 1) for _ in range(length + 1)]
        for i in range(length + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        # If x has t set bits, it is reducible exactly when t reaches 1
        # in at most k-1 further applications.
        good = [False] * (length + 1)
        for t in range(1, length + 1):
            value = t
            steps = 0
            while value != 1:
                value = value.bit_count()
                steps += 1
            good[t] = steps <= k - 1

        answer = 0
        prefix_ones = 0
        for pos, bit in enumerate(s):
            if bit == '1':
                remaining = length - pos - 1
                # Make this bit zero; the resulting number is then smaller.
                for total_ones in range(1, length + 1):
                    if good[total_ones] and total_ones >= prefix_ones:
                        needed = total_ones - prefix_ones
                        if needed <= remaining:
                            answer = (answer + comb[remaining][needed]) % MOD
                prefix_ones += 1

        return answer

