import sys, heapq

def main():
    input = sys.stdin.readline
    n = int(input())
    graph = [input().strip() for _ in range(n)]
    incoming = [[[] for _ in range(26)] for _ in range(n)]
    outgoing = [[[] for _ in range(26)] for _ in range(n)]
    inf = 10**9
    dist = [[inf] * n for _ in range(n)]
    heap = []
    for i in range(n):
        dist[i][i] = 0
        heapq.heappush(heap, (0, i, i))
        for j, ch in enumerate(graph[i]):
            if ch != '-':
                c = ord(ch) - 97
                outgoing[i][c].append(j)
                incoming[j][c].append(i)
                if dist[i][j] > 1:
                    dist[i][j] = 1
                    heapq.heappush(heap, (1, i, j))

    reachable = sum(dist[i][j] < inf for i in range(n) for j in range(n))
    total = n * n
    largest = 1
    while heap:
        w, u, v = heapq.heappop(heap)
        if dist[u][v] != w:
            continue
        nw = w + 2
        if reachable == total and nw >= largest:
            continue
        for c in range(26):
            for a in incoming[u][c]:
                row = dist[a]
                for b in outgoing[v][c]:
                    if row[b] > nw:
                        if row[b] == inf:
                            reachable += 1
                        row[b] = nw
                        if nw > largest:
                            largest = nw
                        heapq.heappush(heap, (nw, a, b))

    sys.stdout.write('\n'.join(' '.join(str(x if x < inf else -1) for x in row)
                               for row in dist))

if __name__ == '__main__':
