def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, x = data[0], data[1]
    vals = data[2:]
    u = vals[::2]
    d = vals[1::2]
    upper = min(a + b for a, b in zip(u, d))

    def feasible(h):
        lo = max(0, h - d[0])
        hi = min(u[0], h)
        if lo > hi:
            return False
        for i in range(1, n):
            left = max(0, h - d[i])
            right = min(u[i], h)
            lo = max(left, lo - x)
            hi = min(right, hi + x)
            if lo > hi:
                return False
        return True

    low, high = 0, upper + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid

    print(sum(vals) - n * low)

