import heapq


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    H, W, X = data[0], data[1], data[2]
    P, Q = data[3] - 1, data[4] - 1
    values = data[5:]
    n = H * W
    start = P * W + Q
    strength = values[start]

    state = bytearray(n)  # 1 means already in the frontier or absorbed
    state[start] = 1
    frontier = []

    def add(v):
        if not state[v]:
            state[v] = 1
            heapq.heappush(frontier, (values[v], v))

    r, c = divmod(start, W)
    if r:
        add(start - W)
    if r + 1 < H:
        add(start + W)
    if c:
        add(start - 1)
    if c + 1 < W:
        add(start + 1)

    while frontier:
        value, v = frontier[0]
        if value * X >= strength:
            break
        heapq.heappop(frontier)
        strength += value
        r, c = divmod(v, W)
        if r:
            add(v - W)
        if r + 1 < H:
            add(v + W)
        if c:
            add(v - 1)
        if c + 1 < W:
            add(v + 1)

    print(strength)


