def main():
    data=sys.stdin.buffer.read().split()
    if not data:
        return
    n,q=map(int,data[:2])
    s=data[2].decode()
    pre1=[0]*(n+1)
    pre2=[0]*(n+1)
    sl=[]
    for i,ch in enumerate(s,1):
        pre1[i]=pre1[i-1]+(ch=='1')
        pre2[i]=pre2[i-1]+(ch=='2')
        if ch=='/':
            sl.append(i)
    out=[]
    k=3
    for _ in range(q):
        L=int(data[k]); R=int(data[k+1]); k+=2
        a=bisect.bisect_left(sl,L)
        b=bisect.bisect_right(sl,R)
        if a==b:
            out.append('0')
            continue
        def val(j):
            p=sl[j]
            return min(pre1[p-1]-pre1[L-1], pre2[R]-pre2[p])
        lo,hi=a,b
        while lo<hi:
            m=(lo+hi)//2
            p=sl[m]
            if pre1[p-1]-pre1[L-1] >= pre2[R]-pre2[p]:
                hi=m
            else:
                lo=m+1
        best=val(b-1)
        if lo<b:
            best=max(best,val(lo))
        if lo-1>=a:
            best=max(best,val(lo-1))
        out.append(str(2*best+1))
