from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        cap = k
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(cap, fact[i - 1] * i)

        def ways(e: int, o: int, next_parity: int) -> int:
            length = e + o
            odd_slots = (length + 1) // 2 if next_parity == 1 else length // 2
            even_slots = length - odd_slots
            if e != even_slots or o != odd_slots:
                return 0
            return min(cap, fact[e] * fact[o])

        even = n // 2
        odd = (n + 1) // 2
        if ways(even, odd, 0) + ways(even, odd, 1) < k:
            return []

        used = [False] * (n + 1)
        result = []
        remaining_even, remaining_odd = even, odd
        last_parity = -1

        for _ in range(n):
            for value in range(1, n + 1):
                parity = value & 1
                if used[value] or (last_parity != -1 and parity == last_parity):
                    continue
                ne = remaining_even - (parity == 0)
                no = remaining_odd - (parity == 1)
                block = ways(ne, no, 1 - parity)
                if block < k:
                    k -= block
                else:
                    used[value] = True
                    result.append(value)
                    remaining_even, remaining_odd = ne, no
                    last_parity = parity
                    break

        return result

