from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        pref = [0]
        for x in nums:
            pref.append(pref[-1] + x)

        nxt = [n] * n
        stack = []
        for i, x in enumerate(nums):
            while stack and nums[stack[-1]] < x:
                nxt[stack.pop()] = i
            stack.append(i)

        levels = n.bit_length()
        ups = [nxt]
        adds = [[nums[i] * (nxt[i] - i) - (pref[nxt[i]] - pref[i])
                 for i in range(n)]]
        for _ in range(1, levels):
            pu, pa = ups[-1], adds[-1]
            u = [n] * n
            a = [0] * n
            for i in range(n):
                m = pu[i]
                if m < n:
                    u[i] = pu[m]
                    a[i] = pa[i] + pa[m]
            ups.append(u)
            adds.append(a)

        def cost(left: int, right: int) -> int:
            i = left
            result = 0
            for z in range(levels - 1, -1, -1):
                m = ups[z][i]
                if m <= right:
                    result += adds[z][i]
                    i = m
            return result + nums[i] * (right - i + 1) - (pref[right + 1] - pref[i])

        answer = 0
        for left in range(n):
            lo, hi = left, n
            while lo < hi:
                mid = (lo + hi) // 2
                if cost(left, mid) <= k:
                    lo = mid + 1
                else:
                    hi = mid
            answer += lo - left
        return answer

