import sys
from functools import lru_cache

sys.setrecursionlimit(100000)

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m, l = data[:3]
    values = data[3:]
    k = n + m + l
    all_mask = (1 << k) - 1
    initial_t = (1 << n) - 1
    initial_a = ((1 << m) - 1) << n

    @lru_cache(None)
    def winning(takahashi, aoki, turn):
        own = takahashi if turn == 0 else aoki
        if own == 0:
            return False

        table = all_mask ^ (takahashi | aoki)
        remaining = own
        while remaining:
            played_bit = remaining & -remaining
            remaining -= played_bit
            played = played_bit.bit_length() - 1

            if turn == 0:
                next_t, next_a = takahashi ^ played_bit, aoki
            else:
                next_t, next_a = takahashi, aoki ^ played_bit

            # Put the card on the table without taking another card.
            if not winning(next_t, next_a, 1 - turn):
                return True

            # Take any strictly smaller card that was already on the table.
            candidates = table
            while candidates:
                taken_bit = candidates & -candidates
                candidates -= taken_bit
                taken = taken_bit.bit_length() - 1
                if values[taken] < values[played]:
                    if turn == 0:
                        after_t, after_a = next_t | taken_bit, next_a
                    else:
                        after_t, after_a = next_t, next_a | taken_bit
                    if not winning(after_t, after_a, 1 - turn):
                        return True

        return False

    print("Takahashi" if winning(initial_t, initial_a, 0) else "Aoki")

