class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        A, B, C = p.split('*')

        def occurrences(t):
            m = len(t)
            result = [False] * (n + 1)
            if m == 0:
                return result
            pi = [0] * m
            for i in range(1, m):
                j = pi[i - 1]
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    result[i - m + 1] = True
                    j = pi[j - 1]
            return result

        def next_occurrence(t):
            if not t:
                return list(range(n + 1))
            found = occurrences(t)
            sentinel = n + 1
            result = [sentinel] * (n + 1)
            nearest = sentinel
            for i in range(n, -1, -1):
                if found[i]:
                    nearest = i
                result[i] = nearest
            return result

        next_a = next_occurrence(A)
        next_b = next_occurrence(B)
        next_c = next_occurrence(C)
        la, lb, lc = len(A), len(B), len(C)
        answer = n + 1

        if not A:
            starts = range(n + 1)
        else:
            starts = (i for i in range(n + 1) if next_a[i] == i)

        for start in starts:
            after_a = start + la if A else start
            b = next_b[after_a] if after_a <= n else n + 1
            if b > n:
                continue
            after_b = b + lb
            c = next_c[after_b] if after_b <= n else n + 1
            if c <= n:
                answer = min(answer, c + lc - start)

        return -1 if answer == n + 1 else answer

