from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)

        # Construct the required postorder without recursion.
        stack = [(0, 0)]
        postorder = []
        while stack:
            v, exiting = stack.pop()
            if not exiting:
                stack.append((v, 1))
                for u in reversed(children[v]):
                    stack.append((u, 0))
            else:
                postorder.append(v)

        position = [0] * n
        sequence = [''] * n
        for i, v in enumerate(postorder):
            position[v] = i
            sequence[i] = s[v]

        # Manacher radii for odd-length palindromes.
        odd = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - k >= 0 and i + k < n and sequence[i-k] == sequence[i+k]:
                k += 1
            odd[i] = k
            if i + k - 1 > right:
                left, right = i - k + 1, i + k - 1

        # Manacher radii for even-length palindromes; center is between i-1 and i.
        even = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - k - 1 >= 0 and i + k < n and sequence[i-k-1] == sequence[i+k]:
                k += 1
            even[i] = k
            if i + k - 1 > right:
                left, right = i - k, i + k - 1

        # In postorder, each subtree is a contiguous interval ending at its node.
        size = [1] * n
        for v in postorder[:-1]:
            size[parent[v]] += size[v]

        answer = [False] * n
        for v in range(n):
            length = size[v]
            r = position[v]
            l = r - length + 1
            if length & 1:
                answer[v] = odd[(l + r) // 2] >= length // 2 + 1
            else:
                answer[v] = even[(l + r + 1) // 2] >= length // 2
        return answer

