import sys
MOD=998244353

def main():
    input=sys.stdin.readline
    n=int(input())
    s=input().strip()
    # dp[(unmatched white, unmatched black)] after the scanned prefix.
    # An unmatched black is paired with a later white, hence represents an
    # interval crossing the current cut.
    dp={(0,0):1}
    for c in s:
        nd={}
        if c=='W':
            for (a,b),v in dp.items():
                # leave this white to be paired with a later black
                nd[(a+1,b)]=(nd.get((a+1,b),0)+v)%MOD
                # pair it with one of the unmatched black vertices
                if b:
                    nd[(a,b-1)]=(nd.get((a,b-1),0)+v*b)%MOD
        else:
            for (a,b),v in dp.items():
                # pair this black with one of the unmatched whites
                if a:
                    nd[(a-1,b)]=(nd.get((a-1,b),0)+v*a)%MOD
                # leave it to be paired with a later white
                nd[(a,b+1)]=(nd.get((a,b+1),0)+v)%MOD
        # Every proper cut must have a backward added edge.
        if c!='W':
            pass
        nd={k:v for k,v in nd.items() if k[1]>0 or k==(0,0)}
        dp=nd
    print(dp.get((0,0),0)%MOD)
