from typing import List
class Solution:
    def maxEnergyBoost(self, energyDrinkA: List[int], energyDrinkB: List[int]) -> int:
        n=len(energyDrinkA)
        # dp values ending with consuming A/B at hour i
        a0=energyDrinkA[0]
        b0=energyDrinkB[0]
        if n==1:
            return max(a0,b0)
        a1=max(a0, 0)+energyDrinkA[1]
        b1=max(b0, 0)+energyDrinkB[1]
        # switching into hour i can use other at i-2; continuing uses same i-1
        for i in range(2,n):
            na=max(a1, b0)+energyDrinkA[i]
            nb=max(b1, a0)+energyDrinkB[i]
            a0,a1=a1,na
            b0,b1=b1,nb
        return max(a1,b1)

