import sys
import math


def main():
    N = int(sys.stdin.buffer.readline())
    limit = math.isqrt(N)

    sieve = bytearray(b'\x01') * (limit + 1)
    sieve[0] = 0
    if limit >= 1:
        sieve[1] = 0
    for p in range(2, math.isqrt(limit) + 1):
        if sieve[p]:
            start = p * p
            sieve[start:limit + 1:p] = b'\x00' * ((limit - start) // p + 1)

    primes = [i for i in range(2, limit + 1) if sieve[i]]

    # Count pairs of distinct primes p < q with p*q <= sqrt(N).
    pairs = 0
    right = len(primes) - 1
    for left, p in enumerate(primes):
        if right <= left:
            break
        while right > left and p * primes[right] > limit:
            right -= 1
        if right <= left:
            break
        pairs += right - left

    # The other possible form is p^8.
    root8 = 1
    while (root8 + 1) ** 8 <= N:
        root8 += 1
    powers = sum(p <= root8 for p in primes)

    print(pairs + powers)


