import itertools


def main():
    vals = list(map(int, sys.stdin.buffer.read().split()))
    if not vals:
        return
    pos = 0
    n = vals[pos]
    pos += 1

    mg = vals[pos]
    pos += 1
    g = [[False] * n for _ in range(n)]
    for _ in range(mg):
        u, v = vals[pos] - 1, vals[pos + 1] - 1
        pos += 2
        g[u][v] = g[v][u] = True

    mh = vals[pos]
    pos += 1
    h = [[False] * n for _ in range(n)]
    for _ in range(mh):
        u, v = vals[pos] - 1, vals[pos + 1] - 1
        pos += 2
        h[u][v] = h[v][u] = True

    cost = [[0] * n for _ in range(n)]
    for i in range(n - 1):
        for j in range(i + 1, n):
            cost[i][j] = cost[j][i] = vals[pos]
            pos += 1

    answer = 10**30
    for perm in itertools.permutations(range(n)):
        total = 0
        for i in range(n):
            for j in range(i + 1, n):
                if g[i][j] != h[perm[i]][perm[j]]:
                    total += cost[perm[i]][perm[j]]
        if total < answer:
            answer = total

    print(answer)


