from typing import List

class Solution:
    def countPairs(self, nums: List[int]) -> int:
        reachable = []
        for value in nums:
            digits = list(str(value))
            variants = {value}  # no operation
            for i in range(len(digits)):
                for j in range(i + 1, len(digits)):
                    swapped = digits[:]
                    swapped[i], swapped[j] = swapped[j], swapped[i]
                    # int() correctly accounts for a leading zero after swapping.
                    variants.add(int(''.join(swapped)))
            reachable.append(variants)

        answer = 0
        for i in range(len(nums)):
            for j in range(i):
                # Either member may be the one whose digits are swapped.
                if nums[j] in reachable[i] or nums[i] in reachable[j]:
                    answer += 1
        return answer

