import heapq


class Solution:
    def minOperations(self, n: int, m: int) -> int:
        digits = len(str(n))
        limit = 10 ** digits

        # Sieve the numbers that may occur (leading zeroes are allowed
        # while a digit position is being changed).
        is_prime = [True] * limit
        is_prime[0] = False
        if limit > 1:
            is_prime[1] = False
        for p in range(2, int(limit ** 0.5) + 1):
            if is_prime[p]:
                is_prime[p * p:limit:p] = [False] * (
                    (limit - 1 - p * p) // p + 1
                )

        if is_prime[n] or is_prime[m]:
            return -1

        # The initial value is part of the cost.  Every edge to x has
        # weight x, so Dijkstra gives the minimum accumulated cost.
        dist = [float("inf")] * limit
        dist[n] = n
        heap = [(n, n)]
        place_values = [10 ** i for i in range(digits)]

        while heap:
            cost, value = heapq.heappop(heap)
            if cost != dist[value]:
                continue
            if value == m:
                return cost

            for place in place_values:
                digit = (value // place) % 10
                if digit < 9:
                    nxt = value + place
                    if not is_prime[nxt] and cost + nxt < dist[nxt]:
                        dist[nxt] = cost + nxt
                        heapq.heappush(heap, (cost + nxt, nxt))
                if digit > 0:
                    nxt = value - place
                    if not is_prime[nxt] and cost + nxt < dist[nxt]:
                        dist[nxt] = cost + nxt
                        heapq.heappush(heap, (cost + nxt, nxt))

        return -1

