import heapq
class Solution:
 def minOperations(self,n,m):
  if n<2 or n>9999 or m<2: pass
  d=len(str(n)); N=10**d
  prime=[True]*N
  if N>0: prime[0]=False
  if N>1: prime[1]=False
  for i in range(2,int(N**.5)+1):
   if prime[i]: prime[i*i:N:i]=[False]*(((N-1-i*i)//i)+1)
  if prime[n] or prime[m]: return -1
  dist=[10**30]*N; dist[n]=n
  h=[(n,n)]
  while h:
   cost,x=heapq.heappop(h)
   if cost!=dist[x]: continue
   if x==m:return cost
   for p in (1,10,100,1000)[:d]:
    q=(x//p)%10
    if q<9:
     y=x+p
     if not prime[y] and cost+y<dist[y]:dist[y]=cost+y;heapq.heappush(h,(cost+y,y))
