class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)

        # z[i] is the length of the common prefix of nums and nums[i:].
        z = [0] * n
        if n:
            z[0] = n
        left = right = 0
        for i in range(1, n):
            if i <= right:
                z[i] = min(right - i + 1, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] - 1 > right:
                left, right = i, i + z[i] - 1

        # dp[j] while processing i is LCP(nums[i:], nums[j:]).
        # Process j increasingly so dp[j+1] still belongs to the previous row.
        dp = [0] * (n + 1)
        answer = 0
        for i in range(n - 2, 0, -1):
            first_condition = z[i] >= i
            if first_condition:
                answer += n - i - 1

            value = nums[i]
            for j in range(i + 1, n):
                if value == nums[j]:
                    dp[j] = dp[j + 1] + 1
                    if not first_condition and dp[j] >= j - i:
                        answer += 1
                else:
                    dp[j] = 0

        return answer

